const ingredients=[['Protein','20g of get-up-and-go. The heart of every BITE.'],['Almonds','A proper crunch. A warm, nutty finish.'],['Dates','Soft, caramel-like sweetness that brings it all together.'],['Dark chocolate','Deep cocoa. A little intensity. A lot to love.'],['Peanut butter','Smooth, roasted richness in every mouthful.'],['Sea salt','A little finishing touch. A big difference to every bite.']];
const flavors=['Dark Chocolate','Peanut Butter','Almond Sea Salt','Berry Cacao'];
document.querySelector('#ingredient-list').innerHTML=ingredients.map(([n,d])=>`<article><h3>${n}</h3><p>${d}</p></article>`).join('');
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let flavorProgress=0;const flavorSection=document.querySelector('.flavors');const track=document.querySelector('.flavor-track');function jumpFlavor(direction){if(reduced||!window.gsap){track.scrollBy({left:direction*track.querySelector('article').offsetWidth,behavior:'smooth'});return}const target=Math.max(0,Math.min(1,Math.round(flavorProgress*3+direction)/3));window.scrollTo({top:flavorSection.offsetTop+target*(flavorSection.offsetHeight-innerHeight),behavior:'smooth'})}document.querySelector('#flavor-prev').onclick=()=>jumpFlavor(-1);document.querySelector('#flavor-next').onclick=()=>jumpFlavor(1);
let lastIngredient=-1;function storyUpdate(p){const k=Math.min(5,Math.floor(Math.min(.999,p/.83)*6));const rebuilding=p>.87;document.querySelector('#stage-title').innerHTML=rebuilding?'All together.<br><em>All BITE.</em>':'Good things.<br><em>Go in.</em>';document.querySelector('#ingredient-index').textContent=rebuilding?'THE WHOLE PICTURE':`0${k+1} / 06`;document.querySelector('#ingredient-name').textContent=rebuilding?'One big BITE.':ingredients[k][0];document.querySelector('#ingredient-description').textContent=rebuilding?'The crunch. The richness. The little finishing touches. All coming together.':ingredients[k][1];document.querySelector('#stage-label').textContent=rebuilding?'THE GOOD STUFF, TOGETHER':'EXPLORE THE INGREDIENTS';document.querySelector('.story-progress i').style.transform=`scaleX(${p})`;document.querySelector('.photo-story').classList.toggle('rebuild',rebuilding);if(k!==lastIngredient){document.querySelectorAll('.story-photo').forEach((im,i)=>im.classList.toggle('active',i===k));document.querySelector('#photo-caption-name').textContent=ingredients[k][0].toUpperCase();lastIngredient=k;}window.renderIngredientDeck?.(p);}
if(window.gsap&&window.ScrollTrigger&&!reduced){gsap.registerPlugin(ScrollTrigger);gsap.from('.meet-pack',{rotation:15,scale:.6,y:100,scrollTrigger:{trigger:'.meet',start:'top 75%',end:'center center',scrub:1}});ScrollTrigger.create({trigger:'.ingredient-scroll',start:'top top',end:'bottom bottom',onUpdate:s=>storyUpdate(s.progress)});gsap.to(track,{x:()=>-Math.max(0,track.scrollWidth-innerWidth),ease:'none',scrollTrigger:{trigger:'.flavors',start:'top top',end:'bottom bottom',scrub:.6,invalidateOnRefresh:true,onUpdate:s=>{flavorProgress=s.progress;document.querySelector('.flavor-counter').textContent=`0${Math.min(4,Math.floor(s.progress*4)+1)} — 04`}}});gsap.from('.final-packs .pack',{y:120,rotation:0,stagger:.12,scrollTrigger:{trigger:'.final',start:'top 70%',end:'center center',scrub:1}});document.fonts.ready.then(()=>ScrollTrigger.refresh());}else{document.querySelector('.ingredient-scroll').style.height='90svh';document.querySelector('.ingredient-accessible').style.display='block';document.querySelector('.flavors').style.height='auto';document.querySelector('.flavor-pin').style.position='relative';document.querySelector('.flavor-pin').style.height='auto';track.style.width='100%';track.style.overflowX='auto';document.querySelectorAll('.flavor-card').forEach(c=>c.style.flexShrink='0');document.querySelector('.lifestyle').style.height='auto'}


